{"command": "cd .skilled/skills/sk-design/sk-design-md-generator/references/examples; python3 - <<'EOF'
import re
for brand in ["stripe","supabase","vercel"]:
    txt=open(f"{brand}/DESIGN.md").read().splitlines()
    # find colors section
    start=None
    for i,l in enumerate(txt):
        if l.strip()=="## Tokens — Colors": start=i; break
    end=None
    for j in range(start+1,len(txt)):
        if txt[j].startswith("## "): end=j; break
    rows=[l for l in txt[start+1:end] if l.strip().startswith("|") and not re.match(r'^\|[\s\-|:]+\|$', l.strip())]
    print(brand, "colors rows incl header:", len(rows), "data rows:", len(rows)-1)
    for i,l in enumerate(txt):
        if l.strip()=="### Shadows":
            s=i; e=next(k for k in range(i+1,len(txt)) if txt[k].startswith("### ") or txt[k].startswith("## "))
            r=[x for x in txt[s+1:e] if x.strip().startswith("|") and not re.match(r'^\|[\s\-|:]+\|$', x.strip())]
            print("  shadows data rows:", len(r)-1)
EOF"}

